      "translation": "punoj tokën • ndërtoj",
      "explanation": [
        "Ideja kryesore: bebauen është folje me dy kuptime: ndërtoj ndërtesa mbi një truall dhe punoj tokën, arën për bujqësi. Është e pandashme dhe merr kallëzore.",
        "Format: bebaut, bebaute, hat bebaut. Pjesorja bebaut përdoret shpesh si mbiemër: dicht bebaut (i ndërtuar dendur), unbebaut (pa ndërtime). Për ndërtesat thuhet mit Häusern bebauen.",
        "Për arat përdoret edhe anbauen (kultivoj një bimë): Weizen anbauen; bebauen ka kuptim më të gjerë, për punimin e tokës në përgjithësi."
      ],
      "examples": [
        {
          "de": "Das Grundstück wird mit Wohnhäusern bebaut.",
          "lv": "Trualli po ndërtohet me shtëpi banimi."
        },
        {
          "de": "Die Bauern bebauen das Feld mit Weizen.",
          "lv": "Fshatarët e punojnë arën dhe mbjellin grurë."
        },
        {
          "de": "Das Gelände darf nicht bebaut werden.",
          "lv": "Në këtë terren nuk lejohet të ndërtohet."
        },
        {
          "de": "Der Hang ist dicht bebaut.",
          "lv": "Shpati është i ndërtuar dendur."
        }
      ],
      "comparison": [
        {
          "word": "bauen",
          "meaning": "ndërtoj",
          "example": "Sie bauen ein Haus. – Ata ndërtojnë një shtëpi."
        },
        {
          "word": "anbauen",
          "meaning": "kultivoj, shtoj një pjesë ndërtese",
          "example": "Hier baut man Wein an. – Këtu kultivohet rrushi për verë."
        },
        {
          "word": "bearbeiten",
          "meaning": "përpunoj, punoj",
          "example": "Er bearbeitet den Boden. – Ai e punon tokën."
        }
      ],
      "tip": [
        "Në kuptimin e ndërtesave përdoret mit: mit Häusern bebauen; shpesh shihet edhe në pësore: bebaut werden.",
        "E kundërta është unbebaut — pa ndërtime."
      ],
      "important": [
        "Bebauen nuk është e njëjtë me bauen: bauen do të thotë ndërtoj diçka, bebauen — mbuloj tokën me ndërtime.",
        "Në bujqësi, për kultivimin e bimëve përdoret më shpesh anbauen."
      ],
