        "Format: beschränkt sich, beschränkte sich, hat sich beschränkt. Parashtesa be- është e pandashme, prandaj nuk ka ge-.",
        "Pa sich, beschränken do të thotë kufizoj diçka tjetër: die Zahl beschränken. Kur diçka kufizohet vetëm në një fushë, përdoret sich beschränken auf: Das Problem beschränkt sich auf …"
