      "id": "b2-sich-scheren",
      "layout": "standardStudy",
      "translation": "çaj kokën",
      "explanation": [
        "Ideja kryesore: sich scheren um në këtë kuptim është shprehje bisedore me kuptimin të çash kokën për diçka, të kujdesesh, por pothuajse vetëm në mohim ose në pyetje: Er schert sich nicht um die Regeln — ai nuk çan kokë për rregullat.",
        "Format: schert sich, scherte sich, hat sich geschert. Me um + kallëzore (Akkusativ) emërtohet ajo për të cilën çan kokën. Pyetje retorike: Was schert mich das? — ç'më duhet mua?",
        "Mënyra urdhërore e vrazhdë Scher dich weg! do të thotë zhduku! Pa përemrin vetvetor sich, folja scheren do të thotë qeth, pres (Schafe scheren)."
      ],
      "examples": [
        {
          "de": "Er schert sich nicht um die Regeln.",
          "lv": "Ai nuk çan kokë për rregullat."
        },
        {
          "de": "Was schert mich das Gerede der anderen?",
          "lv": "Ç'më duhen mua thashethemet e të tjerëve?"
        },
        {
          "de": "Sie schert sich wenig um ihre Gesundheit.",
          "lv": "Ajo pak kujdeset për shëndetin e saj."
        },
        {
          "de": "Scher dich weg!",
          "lv": "Zhduku!"
        }
      ],
      "comparison": [
        {
          "word": "sich kümmern",
          "meaning": "kujdesem",
          "example": "Ich kümmere mich um die Kinder. – Kujdesem për fëmijët."
        },
        {
          "word": "interessieren",
          "meaning": "interesoj",
          "example": "Das interessiert mich nicht. – Kjo nuk më intereson."
        },
        {
          "word": "scheren",
          "meaning": "qeth",
          "example": "Der Bauer schert die Schafe. – Fshatari i qeth delet."
        }
      ],
      "tip": [
        "Në gjuhën e përditshme sich scheren um dëgjohet zakonisht me nicht: Er schert sich nicht darum.",
        "Nëse do të thuash në mënyrë neutrale „kujdesem”, zgjidh sich kümmern um + kallëzore (Akkusativ)."
      ],
      "important": [
        "sich scheren um zakonisht përdoret në mohim; në pohim tingëllon e pazakontë.",
        "Scher dich weg! është i vrazhdë — mos e përdor në bisedë të sjellshme."
      ],
