      "translation": "nëse • me kusht që",
      "explanation": [
        "Ideja kryesore: sofern është lidhëz nënrenditëse që fut një kusht: nëse, me kusht që. Shpreh se diçka vlen ose ndodh vetëm nëse plotësohet kushti.",
        "Pas sofern fillon një fjali e varur, në të cilën folja qëndron në fund: Ich komme, sofern ich Zeit habe. Fjalia e varur ndahet me presje. Lidhëza është stilistikisht pak më zyrtare se wenn dhe shfaqet shpesh në kontrata dhe rregullore.",
        "Mund të përdoret edhe në formë të shkurtuar: sofern möglich — nëse është e mundur."
      ],
      "examples": [
        {
          "de": "Ich komme, sofern ich Zeit habe.",
          "lv": "Do të vij, nëse kam kohë."
        },
        {
          "de": "Sofern nichts anderes vereinbart ist, gilt der Standardpreis.",
          "lv": "Nëse nuk është rënë dakord ndryshe, vlen çmimi standard."
        },
        {
          "de": "Wir fahren morgen, sofern das Wetter gut ist.",
          "lv": "Nisemi nesër, nëse moti është i mirë."
        },
        {
          "de": "Er hilft, sofern er kann.",
          "lv": "Ai ndihmon, në qoftë se mundet."
        },
        {
          "de": "Sofern es möglich ist, rufe ich dich an.",
          "lv": "Nëse është e mundur, do të të marr në telefon."
        }
      ],
      "comparison": [
        {
          "word": "wenn",
          "meaning": "nëse, kur",
          "example": "Wenn es regnet, bleibe ich zu Hause. – Nëse bie shi, rri në shtëpi."
        },
        {
          "word": "falls",
          "meaning": "në rast se",
          "example": "Falls du kommst, ruf an. – Në rast se vjen, më merr në telefon."
        },
        {
          "word": "soweit",
          "meaning": "me sa",
          "example": "Soweit ich weiß, ist er krank. – Me sa di unë, ai është i sëmurë."
        }
      ],
      "tip": [
        "sofern përdoret kur do të theksosh kushtin: Sofern keine Einwände bestehen, …",
        "Mbaj mend renditjen e fjalëve: sofern + kryefjalë + … + folja në fund."
      ],
      "important": [
        "Pas sofern folja është në fund të fjalisë së varur, jo në vendin e dytë.",
        "sofern nuk është e njëjta gjë me soweit (me sa, deri ku): soweit tregon masën, sofern — kushtin."
      ],
